import axios, { AxiosResponse } from "axios";
import { FACE_DETECTION_MESSAGE } from "../constants/api";
import { FACE_DETECTION } from "../constants/endpoints";
import { config } from "../config";


test('Face detection api', async () => {
    var response = await axios.post(`${config.apiURL}${FACE_DETECTION}`, {
        "processParam": {
            "onlyCentralFace": false,
            "outputImageParams": {
                "crop": {
                    "type": 1,
                    "size": [
                        106,
                        134
                    ]
                }
            },
            "attributes": {
                "config": [
                    {
                        "name": "Age"
                    },
                    {
                        "name": "EyeRight"
                    },
                    {
                        "name": "EyeLeft"
                    },
                    {
                        "name": "Emotion"
                    },
                    {
                        "name": "Smile"
                    },
                    {
                        "name": "Glasses"
                    },
                    {
                        "name": "HeadCovering"
                    },
                    {
                        "name": "ForeheadCovering"
                    },
                    {
                        "name": "Mouth"
                    },
                    {
                        "name": "MedicalMask"
                    },
                    {
                        "name": "Occlusion"
                    },
                    {
                        "name": "StrongMakeup"
                    },
                    {
                        "name": "Headphones"
                    }
                ]
            }
        },
        "image": ""
    })
        .catch((error) => expect(error).toBeNull())
        .then((response) => { return response as AxiosResponse });

    expect(response.status).toEqual(200);
    expect(response.data.msg).toEqual(FACE_DETECTION_MESSAGE);
    expect(response.data.results).not.toBeNull();
})

